static const CUnit cust_grumpy_o_leave_rest[] = {
    { "That's my whole routine.", cust_grumpy_o_leave_rest0, 7, 111, 0, 24 },
    { "What a shame, what a shame.", cust_grumpy_o_leave_rest1, 11, 21, 0, 27 },
    { "With no seats.", cust_grumpy_o_leave_rest2, 7, 39, 0, 14 },
    { "No appreciation. No tip, I bet.", cust_grumpy_o_leave_rest3, 13, 18, 0, 31 },
    { "I'd close it, but I'm quite comfortable.", cust_grumpy_o_leave_rest4, 15, 108, 0, 40 },
    { "A trifecta of rudeness.", cust_grumpy_o_leave_rest5, 11, 54, 0, 23 },
    { "I ought to leave a little extra for the trouble.", cust_grumpy_o_leave_rest6, 16, 68, 0, 48 },
    { "Waste not.", cust_grumpy_o_leave_rest7, 5, 55, 0, 10 },
    { "No grace. No appreciation for a proper steep.", cust_grumpy_o_leave_rest8, 19, 89, 0, 45 },
    { "The chair and I have an understanding.", cust_grumpy_o_leave_rest9, 13, 80, 0, 38 },
    { "Ridiculous.", cust_grumpy_o_leave_rest10, 6, 71, 0, 11 },
    { "This cafe's too good for them.", cust_grumpy_o_leave_rest11, 8, 9, 0, 30 },
    { "Again.", cust_grumpy_o_leave_rest12, 4, 46, 0, 6 },
    { "As is my right.", cust_grumpy_o_leave_rest13, 6, 22, 0, 15 },
    { "Always has, truth be told.", cust_grumpy_o_leave_rest14, 11, 72, 0, 26 },
    { "Lovely.", cust_grumpy_o_leave_rest15, 5, 79, 0, 7 },
    { "The silence is nicer, honestly.", cust_grumpy_o_leave_rest16, 13, 38, 0, 31 },
    { "Sighing! At a cafe! The nerve.", cust_grumpy_o_leave_rest17, 15, 86, 0, 30 },
    { "Children.", cust_grumpy_o_leave_rest18, 6, 115, 0, 9 },
    { "Shocking. Truly shocking.", cust_grumpy_o_leave_rest19, 13, 67, 0, 25 },
    { "No manners, I tell you.", cust_grumpy_o_leave_rest20, 10, 5, 0, 23 },
    { "And the afternoon stretches out before me, quiet and mine.", cust_grumpy_o_leave_rest21, 20, 102, 0, 58 },
    { "What a small, hurried life.", cust_grumpy_o_leave_rest22, 11, 98, 0, 27 },
    { "That's all you young ones know.", cust_grumpy_o_leave_rest23, 10, 12, 0, 31 },
    { "Philistines.", cust_grumpy_o_leave_rest24, 7, 69, 0, 12 },
    { "I grunted back in solidarity.", cust_grumpy_o_leave_rest25, 14, 104, 0, 29 },
    { "It's a cafe, dear.", cust_grumpy_o_leave_rest26, 7, 47, 0, 18 },
    { "The cardamom buns are still warm.", cust_grumpy_o_leave_rest27, 12, 75, 0, 33 },
    { "I shall claim it.", cust_grumpy_o_leave_rest28, 8, 88, 0, 17 },
    { "More room for my tail to stretch.", cust_grumpy_o_leave_rest29, 12, 7, 0, 33 },
    { "A tragedy in three acts.", cust_grumpy_o_leave_rest30, 12, 77, 0, 24 },
    { "I sip through mine.", cust_grumpy_o_leave_rest31, 8, 82, 0, 19 },
    { "I remember when waiting built character, not complaints.", cust_grumpy_o_leave_rest32, 19, 1, 0, 56 },
    { "Very long.", cust_grumpy_o_leave_rest33, 5, 103, 0, 10 },
    { "My whiskers twitched.", cust_grumpy_o_leave_rest34, 6, 53, 0, 21 },
    { "A swan, no less.", cust_grumpy_o_leave_rest35, 9, 36, 0, 16 },
    { "Now I can hear myself think, and my thoughts are excellent.", cust_grumpy_o_leave_rest36, 19, 64, 0, 59 },
    { "Amateur move.", cust_grumpy_o_leave_rest37, 7, 13, 0, 13 },
    { "The scones just came out of the oven.", cust_grumpy_o_leave_rest38, 12, 30, 0, 37 },
    { "I'll take my time even more now, out of spite.", cust_grumpy_o_leave_rest39, 13, 24, 0, 46 },
};
