static const CUnit cust_grumpy_o_review3_rest[] = {
    { "Unbelievable.", cust_grumpy_o_review3_rest0, 9, 71, 0, 13 },
    { "I hope your tea is always lukewarm.", cust_grumpy_o_review3_rest1, 14, 59, 0, 35 },
    { "Not a warm scone.", cust_grumpy_o_review3_rest2, 6, 109, 0, 17 },
    { "That tells me plenty.", cust_grumpy_o_review3_rest3, 9, 86, 0, 21 },
    { "Three stars? Nonsense.", cust_grumpy_o_review3_rest4, 9, 17, 0, 22 },
    { "I just grumble and come back. That is the review.", cust_grumpy_o_review3_rest5, 15, 105, 0, 49 },
    { "That was a review.", cust_grumpy_o_review3_rest6, 5, 75, 0, 18 },
    { "I have seen kittens show more gratitude with one meow.", cust_grumpy_o_review3_rest7, 18, 80, 0, 54 },
    { "Not for a place this cozy.", cust_grumpy_o_review3_rest8, 9, 41, 0, 26 },
    { "Three stars is a slap in the whiskers.", cust_grumpy_o_review3_rest9, 10, 54, 0, 38 },
    { "Not for this quiet room.", cust_grumpy_o_review3_rest10, 7, 72, 0, 24 },
    { "Where is the star for that?", cust_grumpy_o_review3_rest11, 8, 90, 0, 27 },
    { "The spoon was clean. That's two stars right there.", cust_grumpy_o_review3_rest12, 14, 9, 0, 50 },
    { "That's worth more than three stars.", cust_grumpy_o_review3_rest13, 8, 49, 0, 35 },
    { "Otherwise, hush.", cust_grumpy_o_review3_rest14, 9, 83, 0, 16 },
    { "I've seen kittens give better reviews with a single meow.", cust_grumpy_o_review3_rest15, 16, 56, 0, 57 },
    { "That's what you give a rainy Tuesday, not a cafe this fine.", cust_grumpy_o_review3_rest16, 19, 4, 0, 59 },
    { "That is worth more than your little stars.", cust_grumpy_o_review3_rest17, 10, 79, 0, 42 },
    { "Barely, but it passes.", cust_grumpy_o_review3_rest18, 11, 88, 0, 22 },
    { "That's worth more than your three little stars.", cust_grumpy_o_review3_rest19, 10, 26, 0, 47 },
    { "You have.", cust_grumpy_o_review3_rest20, 3, 78, 0, 9 },
    { "Now it's just noise.", cust_grumpy_o_review3_rest21, 6, 5, 0, 20 },
    { "I grumbled back. That's how you know it's good.", cust_grumpy_o_review3_rest22, 14, 31, 0, 47 },
    { "The saucer was warm. Two stars already.", cust_grumpy_o_review3_rest23, 14, 106, 0, 39 },
    { "I have left warmer reviews for a cardboard box.", cust_grumpy_o_review3_rest24, 16, 119, 0, 47 },
    { "Complain about the weather. Not the scones.", cust_grumpy_o_review3_rest25, 17, 34, 0, 43 },
    { "Three stars is a slap in the whiskers.", cust_grumpy_o_review3_rest26, 10, 100, 0, 38 },
    { "Did you even try the fish-shaped cookies?", cust_grumpy_o_review3_rest27, 17, 11, 0, 41 },
    { "We just grumbled and came back.", cust_grumpy_o_review3_rest28, 10, 19, 0, 31 },
    { "Five stars, easy.", cust_grumpy_o_review3_rest29, 7, 27, 0, 17 },
    { "This cafe owes you nothing.", cust_grumpy_o_review3_rest30, 8, 62, 0, 27 },
    { "Sit down and sip your tea.", cust_grumpy_o_review3_rest31, 9, 81, 0, 26 },
    { "Three stars. I have had better reviews from a cat mid-yawn.", cust_grumpy_o_review3_rest32, 18, 94, 0, 59 },
    { "I've had worse mornings, but I've had better reviews.", cust_grumpy_o_review3_rest33, 14, 8, 0, 53 },
    { "Trust me, you have.", cust_grumpy_o_review3_rest34, 8, 43, 0, 19 },
    { "Shameful.", cust_grumpy_o_review3_rest35, 5, 97, 0, 9 },
    { "Not for this.", cust_grumpy_o_review3_rest36, 4, 14, 0, 13 },
    { "I complain and give a fat tip.", cust_grumpy_o_review3_rest37, 10, 117, 0, 30 },
    { "I call it a tantrum in cursive.", cust_grumpy_o_review3_rest38, 14, 2, 0, 31 },
    { "You should try it sometime.", cust_grumpy_o_review3_rest39, 9, 10, 0, 27 },
};
