static const CUnit cust_tanuki_o_order_rest[] = {
    { "If it is slow, I will count the leaves I own. Four.", cust_tanuki_o_order_rest0, 19, 90, 0, 51 },
    { "I am unhurried the way clouds are unhurried.", cust_tanuki_o_order_rest1, 19, 104, 0, 44 },
    { "No hurry. I've got a whole pocket of patience.", cust_tanuki_o_order_rest2, 16, 58, 0, 46 },
    { "I am ready to wait as long as the counter stands.", cust_tanuki_o_order_rest3, 14, 61, 0, 49 },
    { "I once waited for a chestnut and wrote it a poem.", cust_tanuki_o_order_rest4, 19, 82, 0, 49 },
    { "If it takes long, I will think about acorns.", cust_tanuki_o_order_rest5, 15, 105, 0, 44 },
    { "I once waited a whole winter for a walnut. Worth it.", cust_tanuki_o_order_rest6, 19, 21, 0, 52 },
    { "I once paid with a single perfect leaf. Good day.", cust_tanuki_o_order_rest7, 18, 36, 0, 49 },
    { "I am not going anywhere, clearly.", cust_tanuki_o_order_rest8, 12, 75, 0, 33 },
    { "My wallet is leaves and my heart is calm.", cust_tanuki_o_order_rest9, 13, 77, 0, 41 },
    { "No rush. I've got a leaf to count.", cust_tanuki_o_order_rest10, 12, 31, 0, 34 },
    { "I once waited for a river to turn. It did. Eventually.", cust_tanuki_o_order_rest11, 22, 57, 0, 54 },
    { "I once waited a week for a berry. It was okay.", cust_tanuki_o_order_rest12, 18, 50, 0, 46 },
    { "No pressure at all.", cust_tanuki_o_order_rest13, 7, 7, 0, 19 },
    { "The {item} can take its time.", cust_tanuki_o_order_rest14, 10, 2, 1, 29 },
    { "I'll just stand here and think about acorns.", cust_tanuki_o_order_rest15, 11, 46, 0, 44 },
    { "If it's slow, I'll just philosophize quietly.", cust_tanuki_o_order_rest16, 18, 49, 0, 45 },
    { "I'm a patient creature. Also a lazy one.", cust_tanuki_o_order_rest17, 19, 51, 0, 40 },
    { "Time is a circle, and so is my appetite.", cust_tanuki_o_order_rest18, 18, 47, 0, 40 },
    { "I'm on leaf currency today, hope that's okay.", cust_tanuki_o_order_rest19, 19, 14, 0, 45 },
    { "I once waited for moss to grow and I enjoyed it.", cust_tanuki_o_order_rest20, 18, 71, 0, 48 },
    { "I once waited a whole afternoon for a walnut. Worth it.", cust_tanuki_o_order_rest21, 21, 109, 0, 55 },
    { "I am relaxed the way soup is relaxed.", cust_tanuki_o_order_rest22, 19, 119, 0, 37 },
    { "Do not worry about me. I am worry-proof.", cust_tanuki_o_order_rest23, 16, 118, 0, 40 },
    { "Take the whole afternoon if it helps.", cust_tanuki_o_order_rest24, 13, 94, 0, 37 },
    { "Leaves for payment, gratitude for the wait.", cust_tanuki_o_order_rest25, 19, 115, 0, 43 },
    { "I am a tanuki of simple and slow appetites.", cust_tanuki_o_order_rest26, 19, 98, 0, 43 },
    { "I am in no rush and also no particular mood.", cust_tanuki_o_order_rest27, 17, 79, 0, 44 },
    { "Take a break if you need, I will hold the floor.", cust_tanuki_o_order_rest28, 18, 78, 0, 48 },
    { "My schedule is mostly naps today.", cust_tanuki_o_order_rest29, 13, 3, 0, 33 },
    { "Take your time, I will admire the counter.", cust_tanuki_o_order_rest30, 14, 110, 0, 42 },
    { "If you forget me, I will simply become scenery.", cust_tanuki_o_order_rest31, 18, 99, 0, 47 },
    { "Rushing gives me a headache, so I stopped.", cust_tanuki_o_order_rest32, 18, 88, 0, 42 },
    { "I'm a firm believer in slow snacks.", cust_tanuki_o_order_rest33, 14, 37, 0, 35 },
    { "I'll pay in leaves and a sincere nod.", cust_tanuki_o_order_rest34, 15, 32, 0, 37 },
    { "I'm not in a hurry, I'm in a mood.", cust_tanuki_o_order_rest35, 14, 33, 0, 34 },
    { "I've been thinking about it since last Tuesday.", cust_tanuki_o_order_rest36, 15, 8, 0, 47 },
    { "If it takes forever, I'll still say thank you.", cust_tanuki_o_order_rest37, 15, 41, 0, 46 },
    { "I'm a patient tanuki. Mostly because I'm sleepy.", cust_tanuki_o_order_rest38, 18, 28, 0, 48 },
    { "If it takes a while, I will simply exist nearby.", cust_tanuki_o_order_rest39, 20, 65, 0, 48 },
};
