static const CUnit mako_v_gossip_kittens_rest[] = {
    { "I came to verify. They did.", mako_v_gossip_kittens_rest0, 12, 60, 0, 27 },
    { "I confirmed it myself.", mako_v_gossip_kittens_rest1, 10, 10, 0, 22 },
    { "Because I count things. Obviously.", mako_v_gossip_kittens_rest2, 15, 36, 0, 34 },
    { "It suits you. Ignore that.", mako_v_gossip_kittens_rest3, 12, 27, 0, 26 },
    { "The kittens noticed. So did I. Shut up.", mako_v_gossip_kittens_rest4, 15, 97, 0, 39 },
    { "Nia is mistaken. Kindly.", mako_v_gossip_kittens_rest5, 14, 47, 0, 24 },
    { "I heard it. It worked, I guess.", mako_v_gossip_kittens_rest6, 13, 44, 0, 31 },
    { "Off key. They fell asleep anyway. Noted.", mako_v_gossip_kittens_rest7, 16, 67, 0, 40 },
    { "Third.", mako_v_gossip_kittens_rest8, 4, 31, 0, 6 },
    { "That's me.", mako_v_gossip_kittens_rest9, 3, 57, 0, 10 },
    { "Wet, furious, adorable. I stayed calm. Mostly.", mako_v_gossip_kittens_rest10, 22, 87, 0, 46 },
    { "They prefer my shoelaces. Your mouse is losing.", mako_v_gossip_kittens_rest11, 21, 82, 0, 47 },
    { "That is a serious metric.", mako_v_gossip_kittens_rest12, 12, 45, 0, 25 },
    { "I answer them every time.", mako_v_gossip_kittens_rest13, 9, 113, 0, 25 },
    { "Gutsy. Reckless. Fine, good work.", mako_v_gossip_kittens_rest14, 17, 70, 0, 33 },
    { "I saw. That was the right one to hold.", mako_v_gossip_kittens_rest15, 12, 2, 0, 38 },
    { "This changes nothing. No, it doesn't.", mako_v_gossip_kittens_rest16, 13, 23, 0, 37 },
    { "I retrieved her in three steps. Record time.", mako_v_gossip_kittens_rest17, 20, 107, 0, 44 },
    { "I hate that you did.", mako_v_gossip_kittens_rest18, 8, 19, 0, 20 },
    { "Secret, got it?", mako_v_gossip_kittens_rest19, 8, 117, 0, 15 },
    { "Chilling. Wonderful.", mako_v_gossip_kittens_rest20, 10, 103, 0, 20 },
    { "It's Stacks. Don't argue.", mako_v_gossip_kittens_rest21, 11, 4, 0, 25 },
    { "Say nothing. Just accept it.", mako_v_gossip_kittens_rest22, 13, 12, 0, 28 },
    { "Mistake.", mako_v_gossip_kittens_rest23, 4, 104, 0, 8 },
    { "I have no comment.", mako_v_gossip_kittens_rest24, 7, 77, 0, 18 },
    { "I nearly applauded.", mako_v_gossip_kittens_rest25, 9, 93, 0, 19 },
    { "Cats don't sit. Mine does.", mako_v_gossip_kittens_rest26, 11, 53, 0, 26 },
    { "Then again. Then you did it too far.", mako_v_gossip_kittens_rest27, 13, 110, 0, 36 },
    { "I handled the cuddles. Balanced roles.", mako_v_gossip_kittens_rest28, 19, 85, 0, 38 },
    { "I have been here five.", mako_v_gossip_kittens_rest29, 6, 24, 0, 22 },
    { "Anyway.", mako_v_gossip_kittens_rest30, 2, 3, 0, 7 },
    { "I did the two a.m. We are even. We are not even.", mako_v_gossip_kittens_rest31, 17, 62, 0, 48 },
    { "In a week they won't. Exciting.", mako_v_gossip_kittens_rest32, 15, 49, 0, 31 },
    { "Hero stuff. Casual.", mako_v_gossip_kittens_rest33, 12, 76, 0, 19 },
    { "There.", mako_v_gossip_kittens_rest34, 3, 114, 0, 6 },
    { "They ignored it. I rebuilt it.", mako_v_gossip_kittens_rest35, 16, 98, 0, 30 },
    { "Annoying.", mako_v_gossip_kittens_rest36, 6, 65, 0, 9 },
    { "I almost cried. Almost. Don't write that down.", mako_v_gossip_kittens_rest37, 16, 18, 0, 46 },
    { "I noticed. Of course I noticed.", mako_v_gossip_kittens_rest38, 13, 0, 0, 31 },
    { "You were already someone. Anyway.", mako_v_gossip_kittens_rest39, 8, 58, 0, 33 },
};
