static const CUnit kuro_v_gossip_fish_rest[] = {
    { "I call that a good conversation.", kuro_v_gossip_fish_rest0, 10, 119, 0, 32 },
    { "That is why you got {n}.", kuro_v_gossip_fish_rest1, 9, 117, 1, 24 },
    { "The fish came like rain. {n} of them.", kuro_v_gossip_fish_rest2, 13, 39, 1, 37 },
    { "It likes your quiet.", kuro_v_gossip_fish_rest3, 6, 43, 0, 20 },
    { "Off-key, but singing.", kuro_v_gossip_fish_rest4, 11, 63, 0, 21 },
    { "You must have waited twice as long.", kuro_v_gossip_fish_rest5, 10, 11, 0, 35 },
    { "That is the whole recipe.", kuro_v_gossip_fish_rest6, 8, 18, 0, 25 },
    { "I hope you left the little ones for next spring.", kuro_v_gossip_fish_rest7, 14, 40, 0, 48 },
    { "You got them by watching. Better.", kuro_v_gossip_fish_rest8, 12, 72, 0, 33 },
    { "Ignore the heron.", kuro_v_gossip_fish_rest9, 8, 71, 0, 17 },
    { "It gave you {n} and kept its dignity.", kuro_v_gossip_fish_rest10, 17, 109, 1, 37 },
    { "I tell them, the boy knows where the shadows sit.", kuro_v_gossip_fish_rest11, 18, 8, 0, 49 },
    { "Both true, I think.", kuro_v_gossip_fish_rest12, 8, 15, 0, 19 },
    { "You learned both.", kuro_v_gossip_fish_rest13, 6, 95, 0, 17 },
    { "The wind is a gossip.", kuro_v_gossip_fish_rest14, 8, 104, 0, 21 },
    { "That is the secret.", kuro_v_gossip_fish_rest15, 6, 16, 0, 19 },
    { "Then I saw your grin.", kuro_v_gossip_fish_rest16, 8, 83, 0, 21 },
    { "It sent {n} your way.", kuro_v_gossip_fish_rest17, 9, 108, 1, 21 },
    { "No better magic.", kuro_v_gossip_fish_rest18, 6, 113, 0, 16 },
    { "It is fond of you now.", kuro_v_gossip_fish_rest19, 8, 19, 0, 22 },
    { "I taught you nothing.", kuro_v_gossip_fish_rest20, 6, 35, 0, 21 },
    { "The heron is a show-off.", kuro_v_gossip_fish_rest21, 11, 30, 0, 24 },
    { "You will get more.", kuro_v_gossip_fish_rest22, 5, 100, 0, 18 },
    { "The water never lies about fish.", kuro_v_gossip_fish_rest23, 8, 21, 0, 32 },
    { "All {n} of them.", kuro_v_gossip_fish_rest24, 8, 69, 1, 16 },
    { "The moon likes a quiet cat.", kuro_v_gossip_fish_rest25, 9, 50, 0, 27 },
    { "You will catch more, but this is a fine start.", kuro_v_gossip_fish_rest26, 13, 26, 0, 46 },
    { "It keeps the rest for winter.", kuro_v_gossip_fish_rest27, 10, 3, 0, 29 },
    { "Then I saw your grin and believed.", kuro_v_gossip_fish_rest28, 13, 23, 0, 34 },
    { "Reeds are terrible gossips.", kuro_v_gossip_fish_rest29, 14, 12, 0, 27 },
    { "You have both.", kuro_v_gossip_fish_rest30, 5, 66, 0, 14 },
    { "That is a conversation, not a catch.", kuro_v_gossip_fish_rest31, 13, 10, 0, 36 },
    { "Frogs exaggerate. But still.", kuro_v_gossip_fish_rest32, 13, 116, 0, 28 },
    { "Good riddance.", kuro_v_gossip_fish_rest33, 7, 17, 0, 14 },
    { "That is a good day.", kuro_v_gossip_fish_rest34, 6, 46, 0, 19 },
    { "It creaked when you landed {n}.", kuro_v_gossip_fish_rest35, 13, 106, 1, 31 },
    { "For reeds, that is much.", kuro_v_gossip_fish_rest36, 10, 98, 0, 24 },
    { "That is rare.", kuro_v_gossip_fish_rest37, 5, 118, 0, 13 },
    { "They were excited, for reeds.", kuro_v_gossip_fish_rest38, 12, 111, 0, 29 },
    { "Now the pond will expect better bait from you.", kuro_v_gossip_fish_rest39, 13, 48, 0, 46 },
};
